import React, { useState, useEffect } from "react";
import { X } from "lucide-react";

function JobForm({ job, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    title: "",
    role: "",
    skillset: "",
    ctc: "",
    location: "",
    experience: "",
    jobType: "Full-time",
    department: "",
    description: "",
    responsibilities: "",
    qualifications: "",
    benefits: "",
    deadline: "",
  });

  useEffect(() => {
    if (job) setFormData(job);
  }, [job]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = () => {
    // Mandatory fields check
    const required = ["title","role","skillset","ctc","location","experience","description"];
    for (let f of required) {
      if (!formData[f]) return alert(`${f} is mandatory!`);
    }
    onSubmit(formData);
  };

  return (
    <div style={overlay}>
      <div style={modal}>
        <div style={header}>
          <h2>{job ? "Edit Job" : "Add Job"}</h2>
          <button onClick={onClose}><X size={20} /></button>
        </div>
        <div style={content}>
          {Object.keys(formData).map((field) => (
            <div key={field} style={{ marginBottom: "12px" }}>
              <label>{field}</label>
              {field === "jobType" ? (
                <select name={field} value={formData[field]} onChange={handleChange}>
                  <option>Full-time</option>
                  <option>Part-time</option>
                  <option>Contract</option>
                  <option>Internship</option>
                </select>
              ) : ["description","responsibilities","qualifications","benefits"].includes(field) ? (
                <textarea name={field} rows={3} value={formData[field]} onChange={handleChange}/>
              ) : (
                <input type={field === "deadline" ? "date" : "text"} name={field} value={formData[field]} onChange={handleChange}/>
              )}
            </div>
          ))}
        </div>
        <div>
          <button onClick={handleSubmit}>{job ? "Update" : "Add"}</button>
          <button onClick={onClose}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

// Minimal styles (you can use your previous styles)
const overlay = { position:"fixed", top:0,left:0,right:0,bottom:0, background:"rgba(0,0,0,0.6)", display:"flex", justifyContent:"center", alignItems:"center" };
const modal = { background:"#fff", padding:"20px", borderRadius:"10px", width:"90%", maxWidth:"600px" };
const header = { display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"20px" };
const content = { maxHeight:"60vh", overflowY:"auto" };

export default JobForm;
